import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError("File does not exist")

    with open(file_path, "r") as f:
        data = json.load(f)

    for field in INPUT_JSON["required"]:
        if field not in data or not isinstance(data[field], INPUT_JSON["properties"][field]["type"]):
            raise ValueError(f"Missing or invalid type for required field: {field}")

    if not re.match(EMAIL_REGEX, data["email"]):
        raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute {attribute} not found")

    return data[attribute]

