import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    response = requests.get(url, params=parameters, headers=HEADERS)
    if response.status_code != 200:
        raise Exception("Failed to access the URL")
    data = json.loads(response.text)
    if not data:
        raise Exception("Empty data received")
    df = pd.DataFrame(data)
    if df.empty or df.select_dtypes(include=['number']).empty:
        raise Exception("Invalid or non-numerical data")
    correlation_matrix = df.corr()
    ax = sns.heatmap(correlation_matrix, annot=True, cmap='coolwarm')
    return df, ax

